(function(){
  var b=Array.from(document.querySelectorAll("[class*=submit]")).find(function(e){return (e.textContent||"").trim().indexOf("发布文章")>=0});
  var el=b, vm=null;
  while(el&&!vm){if(el.__vue__)vm=el.__vue__;el=el.parentElement}
  if(!vm) return "NO_VM";
  var root=vm.$root;
  var keys=Object.keys(root.$data||{});
  var data={};
  keys.forEach(function(k){var v=root.$data[k];if(typeof v!=="object"||v===null)data[k]=v;else if(Array.isArray(v))data[k]="array["+v.length+"]";else data[k]="object:"+(Object.keys(v).slice(0,8).join(","))});
  return JSON.stringify({keys:keys.slice(0,40),data:data});
})()
